PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorBirthDate ?otherFilm ?otherDirector ?otherDirectorBirthDate WHERE {
  VALUES (?film ?otherFilm) {
    (dbr:Tall_Man_Riding dbr:ealvar_Davas) 
    (dbr:ealvar_Davas dbr:Tall_Man_Riding)
  }
  ?film dbo:director ?director .
  ?otherFilm dbo:director ?otherDirector .

  OPTIONAL { ?director dbo:birthDate ?directorBirthDate. }
  OPTIONAL { ?director dbp:birthDate ?directorBirthDateAlt. }
  OPTIONAL { ?otherDirector dbo:birthDate ?otherDirectorBirthDate. }
  OPTIONAL { ?otherDirector dbp:birthDate ?otherDirectorBirthDateAlt. }

  BIND(COALESCE(?directorBirthDate, ?directorBirthDateAlt) AS ?directorBirthDate)
  BIND(COALESCE(?otherDirectorBirthDate, ?otherDirectorBirthDateAlt) AS ?otherDirectorBirthDate)

  FILTER(bound(?directorBirthDate) && bound(?otherDirectorBirthDate) && (?directorBirthDate > ?otherDirectorBirthDate))

  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(langMatches(lang(?filmLabel), "EN")) }
}
LIMIT 10

